import sys
from sortedcontainers import SortedList

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    q = int(data[0])
    index = 1
    operations = []

    for _ in range(q):
        op_type = data[index]
        if op_type == "set":
            ai = data[index + 1]
            xi = int(data[index + 2])
            operations.append((op_type, ai, xi))
            index += 3
        elif op_type == "remove":
            ai = data[index + 1]
            operations.append((op_type, ai))
            index += 2
        elif op_type == "query":
            ai = data[index + 1]
            operations.append((op_type, ai))
            index += 2
        elif op_type == "undo":
            di = int(data[index + 1])
            operations.append((op_type, di))
            index += 2

    todo_list = {}
    priority_list = SortedList()
    history = []

    for op in operations:
        if op[0] == "set":
            ai, xi = op[1], op[2]
            if ai in todo_list:
                old_priority = todo_list[ai]
                priority_list.discard(old_priority)
            todo_list[ai] = xi
            priority_list.add(xi)
            history.append(("set", ai, xi))
        elif op[0] == "remove":
            ai = op[1]
            if ai in todo_list:
                priority = todo_list[ai]
                priority_list.discard(priority)
                del todo_list[ai]
                history.append(("remove", ai))
        elif op[0] == "query":
            ai = op[1]
            if ai in todo_list:
                priority = todo_list[ai]
                count = priority_list.bisect_left(priority)
                print(count)
                sys.stdout.flush()
            else:
                print(-1)
                sys.stdout.flush()
        elif op[0] == "undo":
            di = op[1]
            while len(history) > di:
                last_op = history.pop()
                if last_op[0] == "set":
                    ai, xi = last_op[1], last_op[2]
                    if ai in todo_list:
                        old_priority = todo_list[ai]
                        priority_list.discard(old_priority)
                        if xi != old_priority:
                            priority_list.add(old_priority)
                elif last_op[0] == "remove":
                    ai = last_op[1]
                    if ai not in todo_list:
                        priority = todo_list[ai]
                        priority_list.add(priority)
                        todo_list[ai] = priority

if __name__ == "__main__":
    main()
